+/**
+ * @file automation_controller.cpp
+ * @brief Automation controller implementation for smart environment system
+ */
+
+#include "automation_controller.h"
+#include "../system/diagnostics.h"
+
+float AutomationController::temperatureThreshold = 25.0; // Default 25°C
+float AutomationController::temperatureHysteresis = 2.0; // Default 2°C hysteresis
+float AutomationController::airQualityThreshold = 800.0; // Default unsafe threshold
+unsigned long AutomationController::lightTimeout = 30000; // Default 30 seconds
+bool AutomationController::fanState = false;
+bool AutomationController::lightState = false;
+unsigned long AutomationController::lightLastMotionTime = 0;
+
+void AutomationController::begin() {
+    Serial.println("Initializing automation controller...");
+    // Initialize relay controller
+    RelayController::begin();
+    Serial.println("Automation controller initialized");
+}
+
+void AutomationController::update(OperationMode mode) {
+    if (mode != OperationMode::AUTO_MODE && mode != OperationMode::ALARM_MODE) {
+        // In manual mode, automation is disabled - relays controlled manually
+        return;
+    }
+    
+    // In auto mode or alarm mode, apply automation logic
+    updateFanControl();
+    updateLightControl();
+    updateBuzzerControl();
+}
+
+void AutomationController::setTemperatureThreshold(float threshold) {
+    temperatureThreshold = threshold;
+    Serial.printf("Temperature threshold set to: %.1f°C\n", temperatureThreshold);
+}
+
+void AutomationController::setHysteresis(float hysteresis) {
+    temperatureHysteresis = hysteresis;
+    Serial.printf("Temperature hysteresis set to: %.1f°C\n", temperatureHysteresis);
+}
+
+void AutomationController::setAirQualityThreshold(float threshold) {
+    airQualityThreshold = threshold;
+    Serial.printf("Air quality threshold set to: %.1f\n", airQualityThreshold);
+}
+
+void AutomationController::setLightTimeout(unsigned long timeout) {
+    lightTimeout = timeout;
+    Serial.printf("Light timeout set to: %lu ms\n", lightTimeout);
+}
+
+void AutomationController::updateFanControl() {
+    fanState = RelayController::getFanState();
+    float temperature = TemperatureSensor::getTemperature();
+    bool fanShouldBeOn = false;
+    
+    // Apply hysteresis logic
+    if (fanState) {
+        // Fan is currently ON - turn off when temp < threshold - hysteresis
+        if (temperature < (temperatureThreshold - temperatureHysteresis)) {
+            fanShouldBeOn = false;
+        } else {
+            fanShouldBeOn = true; // Keep ON
+        }
+    } else {
+        // Fan is currently OFF - turn on when temp > threshold
+        if (temperature > temperatureThreshold) {
+            fanShouldBeOn = true;
+        } else {
+            fanShouldBeOn = false; // Keep OFF
+        }
+    }
+    
+    // Update fan state if changed
+    if (fanShouldBeOn != fanState) {
+        fanState = fanShouldBeOn;
+        RelayController::setFan(fanState);
+        
+        if (fanState) {
+            Serial.println("Fan turned ON (temperature control)");
+            Diagnostics::logEvent("Fan ON - Temperature control");
+        } else {
+            Serial.println("Fan turned OFF (temperature control)");
+            Diagnostics::logEvent("Fan OFF - Temperature control");
+        }
+    }
+}
+
+void AutomationController::updateLightControl() {
+    lightState = RelayController::getLightState();
+    bool isDark = LightSensor::isDark();
+    bool motionDetected = MotionSensor::getMotionDetected();
+    unsigned long now = millis();
+    
+    bool lightShouldBeOn = lightState;
+    
+    // Light ON if: dark AND motion detected
+    if (isDark && motionDetected) {
+        lightShouldBeOn = true;
+        lightLastMotionTime = now; // Reset timeout timer
+    }
+    // Light OFF if: not dark OR (dark but no motion for timeout period)
+    else if (!isDark || 
+             (isDark && (now - lightLastMotionTime > lightTimeout))) {
+        lightShouldBeOn = false;
+    }
+    // Otherwise keep current state
+    
+    // Update light state if changed
+    if (lightShouldBeOn != lightState) {
+        lightState = lightShouldBeOn;
+        RelayController::setLight(lightState);
+        
+        if (lightState) {
+            Serial.println("Light turned ON (motion + dark)");
+            Diagnostics::logEvent("Light ON - Motion + Dark");
+        } else {
+            Serial.println("Light turned OFF (timeout or light)");
+            Diagnostics::logEvent("Light OFF - Timeout or Light");
+        }
+    }
+}
+
+void AutomationController::updateBuzzerControl() {
+    bool airQualityUnsafe = AirQualitySensor::isAirQualityUnsafe();
+    
+    // Buzzer ON if air quality is unsafe
+    if (airQualityUnsafe) {
+        // In a real implementation, this would control a buzzer pin
+        // For now, we'll just log it
+        if (!Diagnostics::isBuzzerActive()) {
+            Serial.println("Buzzer ON - Air quality alert");
+            Diagnostics::logEvent("Buzzer ON - Air quality alert");
+            Diagnostics::setBuzzerActive(true);
+        }
+    } else {
+        // Buzzer OFF if air quality is safe
+        if (Diagnostics::isBuzzerActive()) {
+            Serial.println("Buzzer OFF - Air quality normal");
+            Diagnostics::logEvent("Buzzer OFF - Air quality normal");
+            Diagnostics::setBuzzerActive(false);
+        }
+    }
+}

