+/**
+ * @file relay_controller.cpp
+ * @brief Relay controller implementation for fan and light control
+ */
+
+#include "relay_controller.h"
+
+bool RelayController::initialized = false;
+bool RelayController::fanState = false;
+bool RelayController::lightState = false;
+
+void RelayController::begin() {
+    Serial.println("Initializing relay controller...");
+    pinMode(FAN_RELAY_PIN, OUTPUT);
+    pinMode(LIGHT_RELAY_PIN, OUTPUT);
+    
+    // Initialize relays to OFF state (assuming active-low relays)
+    digitalWrite(FAN_RELAY_PIN, HIGH);
+    digitalWrite(LIGHT_RELAY_PIN, HIGH);
+    
+    initialized = true;
+    fanState = false;
+    lightState = false;
+    
+    Serial.println("Relay controller initialized");
+}
+
+void RelayController::setFan(bool state) {
+    if (!initialized) return;
+    
+    fanState = state;
+    // Assuming active-low relays: LOW = ON, HIGH = OFF
+    digitalWrite(FAN_RELAY_PIN, state ? LOW : HIGH);
+    
+    Serial.printf("Fan relay set to: %s\n", state ? "ON" : "OFF");
+}
+
+void RelayController::setLight(bool state) {
+    if (!initialized) return;
+    
+    lightState = state;
+    // Assuming active-low relays: LOW = ON, HIGH = OFF
+    digitalWrite(LIGHT_RELAY_PIN, state ? LOW : HIGH);
+    
+    Serial.printf("Light relay set to: %s\n", state ? "ON" : "OFF");
+}
+
+bool RelayController::getFanState() {
+    return fanState;
+}
+
+bool RelayController::getLightState() {
+    return lightState;
+}
+
+bool RelayController::isInitialized() {
+    return initialized;
+}
+
+void RelayController::updateRelays() {
+    // This function is called periodically to ensure relays maintain their state
+    // In practice, the state is maintained by the hardware, but we can add safety checks here
+    if (!initialized) return;
+    
+    // Ensure relays are in correct state based on stored values
+    digitalWrite(FAN_RELAY_PIN, fanState ? LOW : HIGH);
+    digitalWrite(LIGHT_RELAY_PIN, lightState ? LOW : HIGH);
+}

