+/**
+ * @file oled_manager.cpp
+ * @brief OLED display manager implementation using I2C
+ */
+
+#include "oled_manager.h"
+#include "../network/wifi_manager.h"
+
+Adafruit_SSD1306 OLEDManager::display(128, 64, &Wire, -1);
+bool OLEDManager::initialized = false;
+
+void OLEDManager::begin() {
+    Serial.println("Initializing OLED display...");
+    
+    // Initialize I2C
+    Wire.begin();
+    
+    // Initialize display
+    if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
+        Serial.println("SSD1306 allocation failed");
+        initialized = false;
+        return;
+    }
+    
+    // Clear the buffer
+    display.clearDisplay();
+    display.display();
+    
+    initialized = true;
+    Serial.println("OLED display initialized");
+}
+
+void OLEDManager::update() {
+    if (!initialized) return;
+    
+    // Update display based on current system state
+    // In a real implementation, this would check the system state
+    // For now, we'll show sensor data
+    updateSensorDisplay();
+}
+
+void OLEDManager::drawBootScreen() {
+    if (!initialized) return;
+    
+    display.clearDisplay();
+    display.setTextSize(1);
+    display.setTextColor(SSD1306_WHITE);
+    display.setCursor(0, 0);
+    display.println("Smart Environment");
+    display.println("Monitoring System");
+    display.println("");
+    display.println("Initializing...");
+    display.display();
+}
+
+void OLEDManager::drawInitializationScreen() {
+    if (!initialized) return;
+    
+    display.clearDisplay();
+    display.setTextSize(1);
+    display.setTextColor(SSD1306_WHITE);
+    display.setCursor(0, 0);
+    display.println("Initializing Sensors");
+    display.println("and Peripherals...");
+    display.display();
+}
+
+void OLEDManager::drawWifiConnectingScreen(String status) {
+    if (!initialized) return;
+    
+    display.clearDisplay();
+    display.setTextSize(1);
+    display.setTextColor(SSD1306_WHITE);
+    display.setCursor(0, 0);
+    display.println("Connecting to WiFi");
+    display.println("");
+    display.println(status);
+    display.display();
+}
+
+void OLEDManager::drawErrorScreen(String error) {
+    if (!initialized) return;
+    
+    display.clearDisplay();
+    display.setTextSize(1);
+    display.setTextColor(SSD1306_WHITE);
+    display.setCursor(0, 0);
+    display.println("SYSTEM ERROR");
+    display.println("");
+    display.println(error);
+    display.display();
+}
+
+void OLEDManager::updateSensorDisplay() {
+    if (!initialized) return;
+    
+    display.clearDisplay();
+    
+    // Show sensor readings
+    display.setTextSize(1);
+    display.setTextColor(SSD1306_WHITE);
+    display.setCursor(0, 0);
+    display.print("T: ");
+    display.print(TemperatureSensor::getTemperature(), 1);
+    display.print("C H:");
+    display.print(TemperatureSensor::getHumidity(), 1);
+    display.println("%");
+    
+    display.print("AQ: ");
+    display.print(AirQualitySensor::getAirQuality(), 0);
+    display.print(" L:");
+    display.print(LightSensor::getLightLevel(), 0);
+    display.println("%");
+    
+    display.print("M: ");
+    display.print(MotionSensor::getMotionDetected() ? "YES" : "NO");
+    display.print(" F:");
+    display.print(RelayController::getFanState() ? "ON" : "OFF");
+    display.print(" L:");
+    display.println(RelayController::getLightState() ? "ON" : "OFF");
+    
+    // Show WiFi status
+    display.setCursor(0, 50);
+    if (WiFiManager::isConnected()) {
+        display.print("WiFi: CONNECTED");
+    } else {
+        display.print("WiFi: DISCONNECTED");
+    }
+    
+    display.display();
+}
+
+void OLEDManager::updateStatusScreen() {
+    // For now, same as sensor display
+    updateSensorDisplay();
+}
+
+void OLEDManager::updateModeIndicator() {
+    // Could show AUTO/MANUAL indicator on display
+    // Implementation would depend on where we want to show it
+}
+
+bool OLEDManager::isInitialized() {
+    return initialized;
+}
+
+// Helper methods for drawing different screens
+void OLEDManager::drawSensorScreen() {
+    updateSensorDisplay();
+}
+
+void OLEDManager::drawStatusScreen() {
+    updateStatusScreen();
+}
+
+void OLEDManager::drawModeScreen() {
+    // Placeholder for mode-specific screen
+}

