@@ -0,0 +1,314 @@
+/**
+ * @file main.cpp
+ * @brief Main application file for Smart Environment Monitoring and Control System
+ */
+
+#include <Arduino.h>
+#include <Preferences.h>
+
+// Core system modules
+#include "sensors/temperature_sensor.h"
+#include "sensors/air_quality_sensor.h"
+#include "sensors/light_sensor.h"
+#include "sensors/motion_sensor.h"
+#include "control/automation_controller.h"
+#include "control/relay_controller.h"
+#include "network/wifi_manager.h"
+#include "network/web_server.h"
+#include "network/websocket_manager.h"
+#include "storage/settings_manager.h"
+#include "storage/data_logger.h"
+#include "display/oled_manager.h"
+#include "system/diagnostics.h"
+#include "system/watchdog.h"
+
+#include "system/operation_mode.h"
+
+// Global state
+OperationMode currentMode = OperationMode::BOOT;
+OperationMode previousMode = OperationMode::BOOT;
+unsigned long modeChangeTime = 0;
+bool manualModeRequested = false;
+
+// Forward declarations
+bool checkAlarmConditions();
+bool attemptErrorRecovery();
+void updateDisplayForMode();
+void handleModeTransitions();
+void initializeSystem();
+void updateSystemComponents();
+
+void setup() {
+    // Start serial communication
+    Serial.begin(115200);
+    Serial.println("\n==================================================");
+    Serial.println("Smart Environment Monitoring and Control System");
+    Serial.println("Version 1.0.0");
+    Serial.println("==================================================");
+    
+    // Initialize diagnostics first so we can log everything
+    Diagnostics::begin();
+    Diagnostics::logEvent("System boot initiated");
+    
+    // Initialize watchdog
+    Watchdog::begin();
+    
+    // Initialize settings manager (loads preferences)
+    SettingsManager::begin();
+    
+    // Show boot screen on OLED
+    OLEDManager::begin();
+    OLEDManager::drawBootScreen();
+    
+    delay(1000); // Brief pause for boot screen
+}
+
+void loop() {
+    // Feed watchdog periodically
+    Watchdog::feed();
+    
+    // Update all system components
+    updateSystemComponents();
+    
+    // Handle mode transitions and state machine
+    handleModeTransitions();
+    
+    // Small delay to prevent watchdog triggering and allow processing
+    delay(10);
+}
+
+void updateSystemComponents() {
+    // Update all sensors
+    TemperatureSensor::update();
+    AirQualitySensor::update();
+    LightSensor::update();
+    MotionSensor::update();
+    
+    // Update controllers
+    AutomationController::update(currentMode);
+    
+    // Update communication modules
+    WiFiManager::updateConnection();
+    WebServer::update();
+    WebSocketManager::update();
+    
+    // Update storage
+    // Settings are loaded at startup and saved synchronously on change.
+    DataLogger::update();
+    
+    // Update display
+    OLEDManager::update();
+    
+    // Update system monitoring
+    Watchdog::update();
+}
+
+void handleModeTransitions() {
+    unsigned long now = millis();
+    
+    // Check for mode change requests from WebSocket or web interface
+    OperationMode requestedMode = WebSocketManager::getRequestedMode();
+    
+    // State machine logic
+    switch (currentMode) {
+        case OperationMode::BOOT:
+            // Boot phase - initialize hardware
+            Diagnostics::logEvent("Entering BOOT state");
+            initializeSystem();
+            currentMode = OperationMode::INITIALIZATION;
+            modeChangeTime = now;
+            break;
+            
+        case OperationMode::INITIALIZATION:
+            // Initialization phase - start all subsystems
+            Diagnostics::logEvent("Entering INITIALIZATION state");
+            // Start all subsystems that weren't started in boot
+            WebServer::begin();
+            WebSocketManager::begin();
+            currentMode = OperationMode::WIFI_CONNECTING;
+            modeChangeTime = now;
+            break;
+            
+        case OperationMode::WIFI_CONNECTING:
+            // WiFi connection phase
+            {
+                String wifiStatus = WiFiManager::getConnectionStatus();
+                OLEDManager::drawWifiConnectingScreen(wifiStatus);
+                
+                if (WiFiManager::isConnected() || WiFiManager::isAccessPointActive()) {
+                    Diagnostics::logEvent("WiFi interface ready");
+                    currentMode = OperationMode::AUTO_MODE; // Default to auto mode
+                    modeChangeTime = now;
+                    OLEDManager::updateSensorDisplay(); // Show normal operation screen
+                } else if (WiFiManager::shouldStartAPMode()) {
+                    Diagnostics::logEvent("Starting AP mode for WiFi provisioning");
+                    WiFiManager::startAccessPoint();
+                    // Stay in WIFI_CONNECTING mode but now in AP mode
+                }
+            }
+            break;
+            
+        case OperationMode::AUTO_MODE:
+            // Automatic operation mode
+            if (requestedMode == OperationMode::MANUAL_MODE) {
+                Diagnostics::logEvent("Mode change requested: AUTO -> MANUAL");
+                currentMode = OperationMode::MANUAL_MODE;
+                modeChangeTime = now;
+            }
+            // Check for alarm conditions
+            else if (checkAlarmConditions()) {
+                Diagnostics::logEvent("Alarm condition detected");
+                currentMode = OperationMode::ALARM_MODE;
+                modeChangeTime = now;
+            }
+            break;
+            
+        case OperationMode::MANUAL_MODE:
+            // Manual operation mode
+            if (requestedMode == OperationMode::AUTO_MODE) {
+                Diagnostics::logEvent("Mode change requested: MANUAL -> AUTO");
+                currentMode = OperationMode::AUTO_MODE;
+                modeChangeTime = now;
+            }
+            // In manual mode, automation is disabled but monitoring continues
+            break;
+            
+        case OperationMode::ALARM_MODE:
+            // Alarm mode - handle critical situations
+            if (!checkAlarmConditions()) {
+                Diagnostics::logEvent("Alarm condition cleared");
+                currentMode = OperationMode::AUTO_MODE; // Return to auto mode
+                modeChangeTime = now;
+            }
+            // In alarm mode, we might have special behaviors like
+            // continuous buzzer, flashing lights, etc.
+            break;
+            
+        case OperationMode::ERROR_RECOVERY:
+            // Error recovery mode
+            // Attempt to recover from errors
+            if (attemptErrorRecovery()) {
+                Diagnostics::logEvent("Error recovery successful");
+                currentMode = previousMode; // Return to previous mode
+                modeChangeTime = now;
+            }
+            break;
+    }
+    
+    // Update OLED based on current mode
+    updateDisplayForMode();
+}
+
+void initializeSystem() {
+    Diagnostics::logEvent("Initializing system components");
+    
+    // Initialize all sensors
+    TemperatureSensor::begin();
+    AirQualitySensor::begin();
+    LightSensor::begin();
+    MotionSensor::begin();
+    
+    // Initialize controllers
+    RelayController::begin();
+    // Automation controller initializes relay controller internally
+    AutomationController::begin();
+    
+    // Initialize communication
+    WiFiManager::begin();
+    
+    // Initialize storage
+    // SettingsManager already begun in setup()
+    DataLogger::begin();
+    
+    // Initialize display
+    // OLEDManager already begun in setup()
+    
+    Diagnostics::logEvent("System initialization complete");
+}
+
+bool checkAlarmConditions() {
+    // Check for critical conditions that require immediate attention
+    bool airQualityCritical = AirQualitySensor::hasError() || 
+                              AirQualitySensor::isAirQualityUnsafe();
+                              
+    bool sensorFailure = TemperatureSensor::hasError() || 
+                         AirQualitySensor::hasError() || 
+                         LightSensor::hasError() || 
+                         MotionSensor::hasError();
+    
+    return airQualityCritical || sensorFailure;
+}
+
+bool attemptErrorRecovery() {
+    // Attempt to recover from errors
+    bool recoverySuccessful = true;
+    
+    // Try to recover sensor errors
+    if (TemperatureSensor::hasError()) {
+        // In a real implementation, we might try to reinitialize
+        Diagnostics::logEvent("Attempting temperature sensor recovery");
+        // TemperatureSensor::begin(); // Would reinitialize
+    }
+    
+    if (AirQualitySensor::hasError()) {
+        Diagnostics::logEvent("Attempting air quality sensor recovery");
+        // AirQualitySensor::begin(); // Would reinitialize
+    }
+    
+    if (LightSensor::hasError()) {
+        Diagnostics::logEvent("Attempting light sensor recovery");
+        // LightSensor::begin(); // Would reinitialize
+    }
+    
+    if (MotionSensor::hasError()) {
+        Diagnostics::logEvent("Attempting motion sensor recovery");
+        // MotionSensor::begin(); // Would reinitialize
+    }
+    
+    // Try to recover WiFi connection
+    if (!WiFiManager::isConnected()) {
+        Diagnostics::logEvent("Attempting WiFi reconnection");
+        WiFiManager::reconnect();
+    }
+    
+    return recoverySuccessful;
+}
+
+void updateDisplayForMode() {
+    if (!OLEDManager::isInitialized()) return;
+    
+    switch (currentMode) {
+        case OperationMode::BOOT:
+            OLEDManager::drawBootScreen();
+            break;
+            
+        case OperationMode::INITIALIZATION:
+            OLEDManager::drawInitializationScreen();
+            break;
+            
+        case OperationMode::WIFI_CONNECTING:
+            {
+                String status = WiFiManager::getConnectionStatus();
+                OLEDManager::drawWifiConnectingScreen(status);
+            }
+            break;
+            
+        case OperationMode::AUTO_MODE:
+            OLEDManager::updateSensorDisplay();
+            break;
+            
+        case OperationMode::MANUAL_MODE:
+            OLEDManager::updateSensorDisplay();
+            // Could add "MANUAL MODE" indicator
+            break;
+            
+        case OperationMode::ALARM_MODE:
+            OLEDManager::updateSensorDisplay();
+            // Could add alarm flashing or special display
+            break;
+            
+        case OperationMode::ERROR_RECOVERY:
+            OLEDManager::drawErrorScreen("System Error - Recovering");
+            break;
+    }
+}

