+AsyncWebServer WebServer::server(80);
+bool WebServer::initialized = false;
+const char* WebServer::PARAM_MESSAGE = "message";
+
+void WebServer::begin() {
+    Serial.println("Initializing web server...");
+    
+    // Serve root dashboard
+    server.on("/", HTTP_GET, [](AsyncWebServerRequest *request){
+        handleRootRequest(request);
+    });
+    
+    // API endpoints
+    server.on("/api/sensors", HTTP_GET, [](AsyncWebServerRequest *request){
+        handleApiSensors(request);
+    });
+    
+    server.on("/api/status", HTTP_GET, [](AsyncWebServerRequest *request){
+        handleApiStatus(request);
+    });
+    
+    server.on("/api/mode", HTTP_POST, [](AsyncWebServerRequest *request){
+        handleApiMode(request);
+    });
+    
+    server.on("/api/relay", HTTP_POST, [](AsyncWebServerRequest *request){
+        handleApiRelay(request);
+    });
+    
+    server.on("/api/settings", HTTP_POST, [](AsyncWebServerRequest *request){
+        handleApiSettings(request);
+    });
+    
+    server.on("/api/logs", HTTP_GET, [](AsyncWebServerRequest *request){
+        handleApiLogs(request);
+    });
+    
+    // Handle not found
+    server.onNotFound([](AsyncWebServerRequest *request){
+        handleNotFound(request);
+    });
+    
+    // Start server
+    server.begin();
+    initialized = true;
+    
+    Serial.println("HTTP web server started");
+}
+
+void WebServer::update() {
+    // AsyncWebServer handles everything in the background
+    // This is just for compatibility with the update pattern
+}
+
+void WebServer::handleRootRequest(AsyncWebServerRequest *request) {
+    String html = getDashboardHTML();
+    request->send(200, "text/html", html);
+}
+
+void WebServer::handleApiSensors(AsyncWebServerRequest *request) {
+    String json = getSensorJSON();
+    request->send(200, "application/json", json);
+}
+
+void WebServer::handleApiStatus(AsyncWebServerRequest *request) {
+    String json = getStatusJSON();
+    request->send(200, "application/json", json);
+}
+
+void WebServer::handleApiMode(AsyncWebServerRequest *request) {
+    if (request->hasParam("mode", true)) {
+        String mode = request->getParam("mode", true)->value();
+        Serial.printf("Received mode change request: %s\n", mode.c_str());
+        
+        // Convert to OperationMode and send via WebSocket
+        if (mode == "auto") {
+            WebSocketManager::setRequestedMode(OperationMode::AUTO_MODE);
+        } else if (mode == "manual") {
+            WebSocketManager::setRequestedMode(OperationMode::MANUAL_MODE);
+        } else {
+            request->send(400, "application/json", "{\"error\":\"invalid mode\"}");
+            return;
+        }
+        
+        request->send(200, "application/json", "{\"status\":\"ok\"}");
+    } else {
+        request->send(400, "application/json", "{\"error\":\"missing mode parameter\"}");
+    }
+}
+
+void WebServer::handleApiRelay(AsyncWebServerRequest *request) {
+    bool fanChanged = false;
+    bool lightChanged = false;
+    
+    if (request->hasParam("fan", true)) {
+        String fanState = request->getParam("fan", true)->value();
+        bool state = (fanState == "on" || fanState == "true" || fanState == "1");
+        RelayController::setFan(state);
+        fanChanged = true;
+        Serial.printf("Fan control request: %s\n", fanState.c_str());
+    }
+    
+    if (request->hasParam("light", true)) {
+        String lightState = request->getParam("light", true)->value();
+        bool state = (lightState == "on" || lightState == "true" || lightState == "1");
+        RelayController::setLight(state);
+        lightChanged = true;
+        Serial.printf("Light control request: %s\n", lightState.c_str());
+    }
+    
+    if (fanChanged || lightChanged) {
+        request->send(200, "application/json", "{\"status\":\"ok\"}");
+    } else {
+        request->send(400, "application/json", "{\"error\":\"no valid parameters\"}");
+    }
+}
+
+void WebServer::handleApiSettings(AsyncWebServerRequest *request) {
+    // Handle settings updates (thresholds, etc.)
+    bool updated = false;
+    
+    if (request->hasParam("temp_threshold", true)) {
+        float threshold = request->getParam("temp_threshold", true)->value().toFloat();
+        SettingsManager::setTemperatureThreshold(threshold);
+        updated = true;
+        Serial.printf("Temperature threshold updated: %.1f\n", threshold);
+    }
+    
+    if (request->hasParam("hysteresis", true)) {
+        float hysteresis = request->getParam("hysteresis", true)->value().toFloat();
+        SettingsManager::setTemperatureHysteresis(hysteresis);
+        updated = true;
+        Serial.printf("Hysteresis updated: %.1f\n", hysteresis);
+    }
+    
+    if (request->hasParam("air_quality_threshold", true)) {
+        float threshold = request->getParam("air_quality_threshold", true)->value().toFloat();
+        SettingsManager::setAirQualityThreshold(threshold);
+        updated = true;
+        Serial.printf("Air quality threshold updated: %.1f\n", threshold);
+    }
+    
+    if (updated) {
+        SettingsManager::save(); // Save to persistent storage
+        if (!SettingsManager::isValid()) {
+            request->send(500, "application/json", "{\"error\":\"settings storage unavailable\"}");
+            return;
+        }
+        request->send(200, "application/json", "{\"status\":\"ok\"}");
+    } else {
+        request->send(400, "application/json", "{\"error\":\"no valid settings parameters\"}");
+    }
+}
+
+void WebServer::handleApiLogs(AsyncWebServerRequest *request) {
+    String logs = Diagnostics::getRecentLogs();
+    request->send(200, "application/json", logs);
+}
+
+void WebServer::handleNotFound(AsyncWebServerRequest *request) {
+    request->send(404, "text/plain", "Not found");
+}
