+/**
+ * @file websocket_manager.cpp
+ * @brief WebSocket manager implementation for real-time communication
+ */
+
+#include "websocket_manager.h"
+#include "../system/diagnostics.h"
+
+WebSocketsServer WebSocketManager::webSocket(81); // WebSocket on port 81
+bool WebSocketManager::initialized = false;
+OperationMode WebSocketManager::requestedMode = OperationMode::AUTO_MODE;
+unsigned long WebSocketManager::lastBroadcastTime = 0;
+
+void WebSocketManager::begin() {
+    Serial.println("Initializing WebSocket manager...");
+    webSocket.begin();
+    webSocket.onEvent(handleWebSocketMessage);
+    initialized = true;
+    Serial.println("WebSocket server started on port 81");
+}
+
+void WebSocketManager::update() {
+    if (!initialized) return;
+    
+    webSocket.loop();
+    
+    // Broadcast sensor data periodically
+    unsigned long now = millis();
+    if (now - lastBroadcastTime >= BROADCAST_INTERVAL) {
+        broadcastSensorData();
+        broadcastStatusData();
+        lastBroadcastTime = now;
+    }
+}
+
+void WebSocketManager::setRequestedMode(OperationMode mode) {
+    requestedMode = mode;
+}
+
+OperationMode WebSocketManager::getRequestedMode() {
+    return requestedMode;
+}
+
+void WebSocketManager::broadcastSensorData() {
+    if (!initialized) return;
+    
+    String json = getSensorJSON();
+    webSocket.broadcastTXT(json);
+}
+
+void WebSocketManager::broadcastStatusData() {
+    if (!initialized) return;
+    
+    String json = getStatusJSON();
+    webSocket.broadcastTXT(json);
+}
+
+void WebSocketManager::handleWebSocketMessage(uint8_t num, WStype_t type, uint8_t * payload, size_t length) {
+    switch (type) {
+        case WStype_DISCONNECTED:
+            Serial.printf("[%u] Disconnected!\n", num);
+            break;
+            
+        case WStype_CONNECTED:
+            {
+                Serial.printf("[%u] Connected from %s url: %.*s\n", num,
+                             webSocket.remoteIP(num).toString().c_str(),
+                             static_cast<int>(length), reinterpret_cast<const char*>(payload));
+                
+                // Send initial data to newly connected client
+                String sensorJson = getSensorJSON();
+                String statusJson = getStatusJSON();
+                webSocket.sendTXT(num, sensorJson);
+                webSocket.sendTXT(num, statusJson);
+            }
+            break;
+            
+        case WStype_TEXT:
+            {
+                String message(reinterpret_cast<const char*>(payload), length);
+                Serial.printf("[%u] Received text: %s\n", num, message.c_str());
+                
+                // Parse incoming WebSocket messages for control commands
+                if (message.startsWith("{\"cmd\":\"mode\"")) {
+                    if (message.indexOf("\"value\":\"auto\"") >= 0) {
+                        setRequestedMode(OperationMode::AUTO_MODE);
+                        Diagnostics::logEvent("WebSocket: Mode changed to AUTO");
+                    } else if (message.indexOf("\"value\":\"manual\"") >= 0) {
+                        setRequestedMode(OperationMode::MANUAL_MODE);
+                        Diagnostics::logEvent("WebSocket: Mode changed to MANUAL");
+                    }
+                } else if (message.startsWith("{\"cmd\":\"relay\"")) {
+                    if (message.indexOf("\"type\":\"fan\"") >= 0) {
+                        bool state = message.indexOf("\"state\":\"on\"") >= 0;
+                        RelayController::setFan(state);
+                        String action = state ? "ON" : "OFF";
+                        Diagnostics::logEvent("WebSocket: Fan " + action);
+                    } else if (message.indexOf("\"type\":\"light\"") >= 0) {
+                        bool state = message.indexOf("\"state\":\"on\"") >= 0;
+                        RelayController::setLight(state);
+                        String action = state ? "ON" : "OFF";
+                        Diagnostics::logEvent("WebSocket: Light " + action);
+                    }
+                } else if (message.startsWith("{\"cmd\":\"settings\"")) {
+                    // Handle settings updates from WebSocket
+                    // This would parse JSON and update thresholds, etc.
+                }
+            }
+            break;
+            
+        case WStype_BIN:
+            Serial.printf("[%u] Received binary length: %u\n", num, length);
+            break;
+            
+        default:
+            break;
+    }
+}
+
+String WebSocketManager::getSensorJSON() {
+    // Same implementation as web server for consistency
+    float temperature = TemperatureSensor::getTemperature();
+    float humidity = TemperatureSensor::getHumidity();
+    float airQuality = AirQualitySensor::getAirQuality();
+    float lightLevel = LightSensor::getLightLevel();
+    bool motion = MotionSensor::getMotionDetected();
+    
+    // Handle sensor errors
+    if (TemperatureSensor::hasError()) {
+        temperature = 0.0;
+        humidity = 0.0;
+    }
+    
+    if (AirQualitySensor::hasError()) {
+        airQuality = 0.0;
+    }
+    
+    if (LightSensor::hasError()) {
+        lightLevel = 0.0;
+    }
+    
+    String json = "{";
+    json += "\"temperature\":" + String(temperature) + ",";
+    json += "\"humidity\":" + String(humidity) + ",";
+    json += "\"airQuality\":" + String(airQuality) + ",";
+    json += "\"lightLevel\":" + String(lightLevel) + ",";
+    json += "\"motion\":" + String(motion ? "true" : "false");
+    json += "}";
+    
+    return json;
+}
+
+String WebSocketManager::getStatusJSON() {
+    bool fanState = RelayController::getFanState();
+    bool lightState = RelayController::getLightState();
+    bool wifiConnected = WiFiManager::isConnected();
+    String ipAddress = WiFiManager::getLocalIP();
+    
+    String json = "{";
+    json += "\"fanState\":" + String(fanState ? "true" : "false") + ",";
+    json += "\"lightState\":" + String(lightState ? "true" : "false") + ",";
+    json += "\"wifiConnected\":" + String(wifiConnected ? "true" : "false") + ",";
+    json += "\"ipAddress\":\"" + ipAddress + "\"";
+    json += "}";
+    
+    return json;
+}

