+/**
+ * @file wifi_manager.cpp
+ * @brief WiFi manager implementation for ESP32 with AP mode provisioning
+ */
+
+#include "wifi_manager.h"
+
+bool WiFiManager::initialized = false;
+bool WiFiManager::apModeActive = false;
+unsigned long WiFiManager::connectionAttemptTime = 0;
+const char* WiFiManager::AP_SSID = "EnvMonitor_Setup";
+const char* WiFiManager::AP_PASSWORD = "setup1234";
+Preferences WiFiManager::preferences;
+
+void WiFiManager::begin() {
+    Serial.println("Initializing WiFi manager...");
+    WiFi.mode(WIFI_STA); // Start in station mode
+    initialized = true;
+    apModeActive = false;
+    connectionAttemptTime = 0;
+    
+    // Try to load stored credentials
+    char ssid[32] = {0};
+    char password[64] = {0};
+    if (loadCredentials(ssid, sizeof(ssid), password, sizeof(password))) {
+        Serial.printf("Found stored credentials: %s\n", ssid);
+        WiFi.begin(ssid, password);
+        connectionAttemptTime = millis();
+    } else {
+        Serial.println("No stored WiFi credentials found");
+    }
+    
+    Serial.println("WiFi manager initialized");
+}
+
+void WiFiManager::updateConnection() {
+    if (!initialized) return;
+    
+    if (apModeActive) {
+        // In AP mode, just maintain the AP
+        return;
+    }
+    
+    if (isConnected()) {
+        // Connected, nothing to do
+        return;
+    }
+    
+    // Not connected, check if we should try to connect or start AP
+    unsigned long now = millis();
+    
+    if (connectionAttemptTime == 0) {
+        // First attempt or after manual reconnect
+        connectToStoredNetwork();
+        connectionAttemptTime = now;
+    } else if (now - connectionAttemptTime > CONNECTION_TIMEOUT) {
+        // Connection timed out, try to start AP mode
+        handleConnectionTimeout();
+    }
+}
+
+bool WiFiManager::isConnected() {
+    return WiFi.status() == WL_CONNECTED;
+}
+
+bool WiFiManager::isAccessPointActive() {
+    return initialized && apModeActive;
+}
+
+bool WiFiManager::shouldStartAPMode() {
+    // Start AP mode if we've been trying to connect for too long
+    if (!initialized) return false;
+    
+    if (connectionAttemptTime == 0) return false;
+    
+    unsigned long now = millis();
+    return (now - connectionAttemptTime > CONNECTION_TIMEOUT) && !apModeActive;
+}
+
+void WiFiManager::startAccessPoint() {
+    Serial.println("Starting Access Point mode...");
+    WiFi.mode(WIFI_AP);
+    WiFi.softAP(AP_SSID, AP_PASSWORD);
+    apModeActive = true;
+    Serial.printf("AP started: %s, IP: %s\n", AP_SSID, WiFi.softAPIP().toString().c_str());
+}
+
+void WiFiManager::stopAccessPoint() {
+    Serial.println("Stopping Access Point mode...");
+    WiFi.softAPdisconnect(true);
+    WiFi.mode(WIFI_STA);
+    apModeActive = false;
+    Serial.println("AP mode stopped");
+}
+
+String WiFiManager::getConnectionStatus() {
+    if (!initialized) return "Not initialized";
+    
+    if (apModeActive) {
+        return "AP Mode: " + String(AP_SSID);
+    }
+    
+    if (isConnected()) {
+        return "Connected: " + WiFi.SSID();
+    }
+    
+    return "Disconnected";
+}
+
+String WiFiManager::getLocalIP() {
+    if (isConnected()) {
+        return WiFi.localIP().toString();
+    } else if (apModeActive) {
+        return WiFi.softAPIP().toString();
+    }
+    return "0.0.0.0";
+}
+
+void WiFiManager::reconnect() {
+    Serial.println("Manual WiFi reconnect requested...");
+    connectionAttemptTime = 0; // Reset to force immediate reconnect
+    apModeActive = false;
+    stopAccessPoint();
+    WiFi.mode(WIFI_STA);
+}
+
+void WiFiManager::saveCredentials(const char* ssid, const char* password) {
+    Serial.println("Saving WiFi credentials...");
+    if (!preferences.begin("wifi-config", false)) {
+        Serial.println("Failed to open preferences");
+        return;
+    }
+    
+    preferences.putString("ssid", ssid);
+    preferences.putString("password", password);
+    preferences.end();
+    
+    Serial.println("WiFi credentials saved");
+}
+
+bool WiFiManager::loadCredentials(char* ssid, size_t ssidSize, char* password, size_t passwordSize) {
+    if (!preferences.begin("wifi-config", true)) {
+        Serial.println("Failed to open preferences for reading");
+        return false;
+    }
+    
+    String storedSsid = preferences.getString("ssid", "");
+    String storedPassword = preferences.getString("password", "");
+    
+    preferences.end();
+    
+    if (storedSsid.length() == 0 || storedPassword.length() == 0) {
+        return false;
+    }
+    
+    // Copy to output buffers
+    strncpy(ssid, storedSsid.c_str(), ssidSize - 1);
+    ssid[ssidSize - 1] = '\0';
+    
+    strncpy(password, storedPassword.c_str(), passwordSize - 1);
+    password[passwordSize - 1] = '\0';
+    
+    return true;
+}
+
+void WiFiManager::connectToStoredNetwork() {
+    char ssid[32] = {0};
+    char password[64] = {0};
+    
+    if (loadCredentials(ssid, sizeof(ssid), password, sizeof(password))) {
+        Serial.printf("Connecting to stored network: %s\n", ssid);
+        WiFi.begin(ssid, password);
+    } else {
+        Serial.println("No stored credentials to connect to");
+    }
+}
+
+void WiFiManager::handleConnectionTimeout() {
+    Serial.println("WiFi connection timeout - starting AP mode");
+    startAccessPoint();
+}

