+/**
+ * @file air_quality_sensor.cpp
+ * @brief Air quality sensor implementation using MQ-135
+ */
+
+#include "air_quality_sensor.h"
+#include "../storage/settings_manager.h"
+
+bool AirQualitySensor::initialized = false;
+bool AirQualitySensor::errorState = false;
+float AirQualitySensor::airQualityValue = 0.0;
+String AirQualitySensor::errorMessage = "";
+unsigned long AirQualitySensor::lastReadTime = 0;
+
+void AirQualitySensor::begin() {
+    Serial.println("Initializing MQ-135 air quality sensor...");
+    pinMode(AIR_QUALITY_PIN, INPUT);
+    initialized = true;
+    errorState = false;
+    errorMessage = "";
+    Serial.println("MQ-135 sensor initialized");
+}
+
+void AirQualitySensor::update() {
+    if (!initialized) return;
+    
+    unsigned long now = millis();
+    if (now - lastReadTime >= READ_INTERVAL) {
+        readSensor();
+        lastReadTime = now;
+    }
+}
+
+void AirQualitySensor::readSensor() {
+    int rawValue = analogRead(AIR_QUALITY_PIN);
+    
+    // Convert to voltage (0-3.3V)
+    float voltage = (rawValue / 4095.0) * 3.3;
+    
+    // Simple conversion to approximate PPM (this would need calibration)
+    // MQ-135 typical range: 10-1000 PPM for various gases
+    airQualityValue = voltage * 100; // Approximate conversion
+    
+    // Basic sanity check
+    if (airQualityValue < 0 || airQualityValue > 5000) { // Unreasonable values
+        errorState = true;
+        errorMessage = "Invalid reading from MQ-135 sensor";
+        Serial.println(errorMessage);
+        return;
+    }
+    
+    errorState = false;
+    errorMessage = "";
+    
+    Serial.printf("Air Quality: %.1f (raw: %d, voltage: %.2fV)\n", 
+                  airQualityValue, rawValue, voltage);
+}
+
+float AirQualitySensor::getAirQuality() {
+    return airQualityValue;
+}
+
+bool AirQualitySensor::isInitialized() {
+    return initialized;
+}
+
+bool AirQualitySensor::hasError() {
+    return errorState;
+}
+
+String AirQualitySensor::getErrorMessage() {
+    return errorMessage;
+}
+
+bool AirQualitySensor::isAirQualityUnsafe() {
+    return airQualityValue > SettingsManager::getAirQualityThreshold();
+}

