+/**
+ * @file light_sensor.cpp
+ * @brief Light sensor implementation using LDR
+ */
+
+#include "light_sensor.h"
+
+bool LightSensor::initialized = false;
+bool LightSensor::errorState = false;
+float LightSensor::lightLevel = 0.0;
+String LightSensor::errorMessage = "";
+unsigned long LightSensor::lastReadTime = 0;
+
+void LightSensor::begin() {
+    Serial.println("Initializing LDR light sensor...");
+    pinMode(LDR_PIN, INPUT);
+    initialized = true;
+    errorState = false;
+    errorMessage = "";
+    Serial.println("LDR light sensor initialized");
+}
+
+void LightSensor::update() {
+    if (!initialized) return;
+    
+    unsigned long now = millis();
+    if (now - lastReadTime >= READ_INTERVAL) {
+        readSensor();
+        lastReadTime = now;
+    }
+}
+
+void LightSensor::readSensor() {
+    int rawValue = analogRead(LDR_PIN);
+    
+    // Convert to percentage (inverted because higher resistance = darker = higher analog value)
+    // LDR gives higher values in darkness, lower values in light
+    lightLevel = 100.0 - ((rawValue / 4095.0) * 100.0);
+    
+    // Basic sanity check
+    if (lightLevel < 0 || lightLevel > 100) {
+        errorState = true;
+        errorMessage = "Invalid reading from LDR sensor";
+        Serial.println(errorMessage);
+        return;
+    }
+    
+    errorState = false;
+    errorMessage = "";
+    
+    Serial.printf("Light Level: %.1f%% (raw: %d)\n", lightLevel, rawValue);
+}
+
+float LightSensor::getLightLevel() {
+    return lightLevel;
+}
+
+bool LightSensor::isInitialized() {
+    return initialized;
+}
+
+bool LightSensor::hasError() {
+    return errorState;
+}
+
+String LightSensor::getErrorMessage() {
+    return errorMessage;
+}
+
+bool LightSensor::isDark() {
+    // Consider dark if light level is below 30%
+    return lightLevel < 30.0;
+}

