+void MotionSensor::begin() {
+    Serial.println("Initializing PIR motion sensor...");
+    pinMode(PIR_PIN, INPUT);
+    initialized = true;
+    errorState = false;
+    errorMessage = "";
+    lastMotionTime = 0;
+    Serial.println("PIR motion sensor initialized");
+}
+
+void MotionSensor::update() {
+    if (!initialized) return;
+    
+    unsigned long now = millis();
+    if (now - lastReadTime >= READ_INTERVAL) {
+        readSensor();
+        lastReadTime = now;
+    }
+}
+
+void MotionSensor::readSensor() {
+    bool currentState = digitalRead(PIR_PIN);
+    
+    if (currentState == HIGH && !motionDetected) {
+        // Motion just started
+        motionDetected = true;
+        lastMotionTime = millis();
+        Serial.println("Motion detected!");
+    } else if (currentState == LOW && motionDetected) {
+        // Motion just ended
+        motionDetected = false;
+        Serial.println("Motion ended");
+    }
+    
+    // Basic error checking (PIR is pretty robust)
+    errorState = false;
+    errorMessage = "";
+}
