+/**
+ * @file data_logger.cpp
+ * @brief Data logger implementation for optional microSD card storage
+ */
+
+#include "data_logger.h"
+#include "../system/diagnostics.h"
+
+bool DataLogger::initialized = false;
+bool DataLogger::enabled = false;
+bool DataLogger::sdCardPresent = false;
+unsigned long DataLogger::lastLogTime = 0;
+const int DataLogger::SD_CS_PIN;
+const char* DataLogger::LOG_FILE_PREFIX = "envlog_";
+const char* DataLogger::LOG_FILE_EXTENSION = ".csv";
+
+void DataLogger::begin() {
+    Serial.println("Initializing data logger...");
+    initialized = true;
+    enabled = true; // Enable by default if SD card is present
+    
+    // Try to initialize SD card
+    sdCardPresent = initializeSDCard();
+    
+    if (sdCardPresent) {
+        Serial.println("microSD card detected - data logging enabled");
+        // Create initial log file if needed
+        String logFile = createLogFilename();
+        if (!SD.exists(logFile.c_str())) {
+            File file = SD.open(logFile.c_str(), FILE_WRITE);
+            if (file) {
+                file.println(formatCSVHeader());
+                file.close();
+                Serial.println("Created new log file: " + logFile);
+            }
+        }
+    } else {
+        Serial.println("No microSD card detected - data logging disabled");
+        enabled = false;
+    }
+}
+
+void DataLogger::update() {
+    if (!initialized || !enabled || !sdCardPresent) return;
+    
+    unsigned long now = millis();
+    if (now - lastLogTime >= LOG_INTERVAL) {
+        logSensorData();
+        lastLogTime = now;
+    }
+}
+
+void DataLogger::logSensorData() {
+    if (!sdCardPresent) return;
+    
+    String csvRow = formatCSVRow();
+    String logFile = createLogFilename();
+    
+    File file = SD.open(logFile.c_str(), FILE_APPEND);
+    if (file) {
+        file.println(csvRow);
+        file.close();
+        Serial.println("Logged sensor data to: " + logFile);
+    } else {
+        Serial.println("Failed to open log file for writing");
+        Diagnostics::logEvent("SD Card write error");
+    }
+}
+
+String DataLogger::getLogFilePath() {
+    if (sdCardPresent) {
+        return createLogFilename();
+    }
+    return "";
+}
+
+bool DataLogger::isEnabled() {
+    return enabled && sdCardPresent;
+}
+
+void DataLogger::setEnabled(bool enabled) {
+    DataLogger::enabled = enabled;
+}
+
+bool DataLogger::initializeSDCard() {
+    Serial.println("Initializing microSD card...");
+    
+    if (!SD.begin(SD_CS_PIN)) {
+        Serial.println("microSD card initialization failed!");
+        return false;
+    }
+    
+    uint8_t cardType = SD.cardType();
+    if (cardType == CARD_NONE) {
+        Serial.println("No microSD card attached");
+        return false;
+    }
+    
+    Serial.print("microSD Card Type: ");
+    if (cardType == CARD_MMC) {
+        Serial.println("MMC");
+    } else if (cardType == CARD_SD) {
+        Serial.println("SDSC");
+    } else if (cardType == CARD_SDHC) {
+        Serial.println("SDHC");
+    } else {
+        Serial.println("UNKNOWN");
+    }
+    
+    uint64_t cardSize = SD.cardSize() / (1024 * 1024);
+    Serial.printf("microSD Card Size: %lluMB\n", cardSize);
+    
+    return true;
+}
+
+String DataLogger::createLogFilename() {
+    // Create filename based on date: envlog_YYYYMMDD.csv
+    // For simplicity, we'll use a counter-based approach since we don't have RTC
+    static int fileCounter = 0;
+    String filename = String(LOG_FILE_PREFIX) + String(fileCounter++) + String(LOG_FILE_EXTENSION);
+    return "/"+filename; // Store in root directory
+}
+
+String DataLogger::formatCSVHeader() {
+    return "Timestamp,Temperature(C),Humidity(%),AirQuality,LightLevel(%),MotionDetected,FanState,LightState";
+}
+
+String DataLogger::formatCSVRow() {
+    unsigned long timestamp = millis();
+    float temperature = TemperatureSensor::getTemperature();
+    float humidity = TemperatureSensor::getHumidity();
+    float airQuality = AirQualitySensor::getAirQuality();
+    float lightLevel = LightSensor::getLightLevel();
+    bool motion = MotionSensor::getMotionDetected();
+    bool fanState = RelayController::getFanState();
+    bool lightState = RelayController::getLightState();
+    
+    // Handle sensor errors
+    if (TemperatureSensor::hasError()) {
+        temperature = 0.0;
+        humidity = 0.0;
+    }
+    
+    if (AirQualitySensor::hasError()) {
+        airQuality = 0.0;
+    }
+    
+    if (LightSensor::hasError()) {
+        lightLevel = 0.0;
+    }
+    
+    String row = String(timestamp) + "," +
+                 String(temperature, 1) + "," +
+                 String(humidity, 1) + "," +
+                 String(airQuality, 1) + "," +
+                 String(lightLevel, 1) + "," +
+                 String(motion ? 1 : 0) + "," +
+                 String(fanState ? 1 : 0) + "," +
+                 String(lightState ? 1 : 0);
+    
+    return row;
+}

