+/**
+ * @file settings_manager.cpp
+ * @brief Settings manager implementation for persistent storage using Preferences/NVS
+ */
+
+#include "settings_manager.h"
+#include "../control/automation_controller.h"
+
+Preferences SettingsManager::preferences;
+bool SettingsManager::initialized = false;
+bool SettingsManager::valid = false;
+
+const char* SettingsManager::NAMESPACE = "env_settings";
+const char* SettingsManager::KEY_TEMP_THRESHOLD = "temp_thresh";
+const char* SettingsManager::KEY_TEMP_HYSTERESIS = "temp_hyst";
+const char* SettingsManager::KEY_AIR_QUALITY_THRESHOLD = "air_thresh";
+const char* SettingsManager::KEY_LIGHT_TIMEOUT = "light_timeout";
+const char* SettingsManager::KEY_BUZZER_ENABLED = "buzzer_en";
+const char* SettingsManager::KEY_AUTO_RECONNECT_WIFI = "wifi_reconnect";
+
+float SettingsManager::temperatureThreshold = 25.0;      // Default 25°C
+float SettingsManager::temperatureHysteresis = 2.0;      // Default 2°C hysteresis
+float SettingsManager::airQualityThreshold = 800.0;      // Default unsafe threshold
+unsigned long SettingsManager::lightTimeout = 30000;     // Default 30 seconds
+bool SettingsManager::buzzerEnabled = true;              // Buzzer enabled by default
+bool SettingsManager::autoReconnectWiFi = true;          // Auto-reconnect enabled by default
+
+void SettingsManager::begin() {
+    Serial.println("Initializing settings manager...");
+    if (!preferences.begin(NAMESPACE, false)) {
+        Serial.println("Failed to open preferences namespace");
+        initialized = false;
+        valid = false;
+        return;
+    }
+    
+    initialized = true;
+    load(); // Load existing settings or use defaults
+    valid = true;
+    
+    Serial.println("Settings manager initialized");
+}
+
+void SettingsManager::save() {
+    if (!initialized) return;
+    // load() closes its handle; each save must reopen NVS.
+    if (!preferences.begin(NAMESPACE, false)) {
+        valid = false;
+        return;
+    }
+    
+    Serial.println("Saving settings to NVS...");
+    
+    preferences.putFloat(KEY_TEMP_THRESHOLD, temperatureThreshold);
+    preferences.putFloat(KEY_TEMP_HYSTERESIS, temperatureHysteresis);
+    preferences.putFloat(KEY_AIR_QUALITY_THRESHOLD, airQualityThreshold);
+    preferences.putULong(KEY_LIGHT_TIMEOUT, lightTimeout);
+    preferences.putBool(KEY_BUZZER_ENABLED, buzzerEnabled);
+    preferences.putBool(KEY_AUTO_RECONNECT_WIFI, autoReconnectWiFi);
+    
+    preferences.end();
+    
+    // Apply settings to controllers
+    AutomationController::setTemperatureThreshold(temperatureThreshold);
+    AutomationController::setHysteresis(temperatureHysteresis);
+    AutomationController::setAirQualityThreshold(airQualityThreshold);
+    AutomationController::setLightTimeout(lightTimeout);
+    valid = true;
+    
+    Serial.println("Settings saved");
+}
+
+void SettingsManager::load() {
+    if (!initialized) return;
+    
+    Serial.println("Loading settings from NVS...");
+    
+    // Load settings with defaults if not found
+    temperatureThreshold = preferences.getFloat(KEY_TEMP_THRESHOLD, 25.0);
+    temperatureHysteresis = preferences.getFloat(KEY_TEMP_HYSTERESIS, 2.0);
+    airQualityThreshold = preferences.getFloat(KEY_AIR_QUALITY_THRESHOLD, 800.0);
+    lightTimeout = preferences.getULong(KEY_LIGHT_TIMEOUT, 30000);
+    buzzerEnabled = preferences.getBool(KEY_BUZZER_ENABLED, true);
+    autoReconnectWiFi = preferences.getBool(KEY_AUTO_RECONNECT_WIFI, true);
+    
+    preferences.end();
+    
+    // Apply loaded settings
+    AutomationController::setTemperatureThreshold(temperatureThreshold);
+    AutomationController::setHysteresis(temperatureHysteresis);
+    AutomationController::setAirQualityThreshold(airQualityThreshold);
+    AutomationController::setLightTimeout(lightTimeout);
+    
+    Serial.println("Settings loaded:");
+    Serial.printf("  Temp threshold: %.1f°C\n", temperatureThreshold);
+    Serial.printf("  Temp hysteresis: %.1f°C\n", temperatureHysteresis);
+    Serial.printf("  Air quality threshold: %.1f\n", airQualityThreshold);
+    Serial.printf("  Light timeout: %lu ms\n", lightTimeout);
+    Serial.printf("  Buzzer enabled: %s\n", buzzerEnabled ? "true" : "false");
+    Serial.printf("  Auto-reconnect WiFi: %s\n", autoReconnectWiFi ? "true" : "false");
+}
+
+bool SettingsManager::isValid() {
+    return initialized && valid;
+}
+
+// Getter and setter implementations
+float SettingsManager::getTemperatureThreshold() {
+    return temperatureThreshold;
+}
+
+void SettingsManager::setTemperatureThreshold(float threshold) {
+    temperatureThreshold = threshold;
+}
+
+float SettingsManager::getTemperatureHysteresis() {
+    return temperatureHysteresis;
+}
+
+void SettingsManager::setTemperatureHysteresis(float hysteresis) {
+    temperatureHysteresis = hysteresis;
+}
+
+float SettingsManager::getAirQualityThreshold() {
+    return airQualityThreshold;
+}
+
+void SettingsManager::setAirQualityThreshold(float threshold) {
+    airQualityThreshold = threshold;
+}
+
+unsigned long SettingsManager::getLightTimeout() {
+    return lightTimeout;
+}
+
+void SettingsManager::setLightTimeout(unsigned long timeout) {
+    lightTimeout = timeout;
+}
+
+bool SettingsManager::getBuzzerEnabled() {
+    return buzzerEnabled;
+}
+
+void SettingsManager::setBuzzerEnabled(bool enabled) {
+    buzzerEnabled = enabled;
+}
+
+bool SettingsManager::getAutoReconnectWiFi() {
+    return autoReconnectWiFi;
+}
+
+void SettingsManager::setAutoReconnectWiFi(bool enabled) {
+    autoReconnectWiFi = enabled;
+}

