+/**
+ * @file diagnostics.cpp
+ * @brief System diagnostics and logging implementation
+ */
+
+#include "diagnostics.h"
+
+bool Diagnostics::initialized = false;
+std::vector<String> Diagnostics::logEntries;
+bool Diagnostics::buzzerActive = false;
+
+void Diagnostics::begin() {
+    Serial.println("Initializing diagnostics...");
+    initialized = true;
+    buzzerActive = false;
+    logEntries.clear();
+    
+    logEvent("System startup");
+    Serial.println("Diagnostics initialized");
+}
+
+void Diagnostics::logEvent(const String& message) {
+    if (!initialized) return;
+    
+    String timestamp = getTimestamp();
+    String logEntry = "[" + timestamp + "] INFO: " + message;
+    
+    // Add to log entries
+    logEntries.push_back(logEntry);
+    
+    // Keep only the most recent entries
+    if (logEntries.size() > MAX_LOG_ENTRIES) {
+        logEntries.erase(logEntries.begin());
+    }
+    
+    // Also output to serial
+    Serial.println(logEntry);
+}
+
+void Diagnostics::logError(const String& message) {
+    if (!initialized) return;
+    
+    String timestamp = getTimestamp();
+    String logEntry = "[" + timestamp + "] ERROR: " + message;
+    
+    // Add to log entries
+    logEntries.push_back(logEntry);
+    
+    // Keep only the most recent entries
+    if (logEntries.size() > MAX_LOG_ENTRIES) {
+        logEntries.erase(logEntries.begin());
+    }
+    
+    // Also output to serial
+    Serial.println(logEntry);
+}
+
+void Diagnostics::logWarning(const String& message) {
+    if (!initialized) return;
+    
+    String timestamp = getTimestamp();
+    String logEntry = "[" + timestamp + "] WARNING: " + message;
+    
+    // Add to log entries
+    logEntries.push_back(logEntry);
+    
+    // Keep only the most recent entries
+    if (logEntries.size() > MAX_LOG_ENTRIES) {
+        logEntries.erase(logEntries.begin());
+    }
+    
+    // Also output to serial
+    Serial.println(logEntry);
+}
+
+String Diagnostics::getRecentLogs() {
+    if (!initialized) return "[]";
+    
+    String json = "[";
+    for (size_t i = 0; i < logEntries.size(); i++) {
+        json += "\"" + logEntries[i] + "\"";
+        if (i < logEntries.size() - 1) {
+            json += ",";
+        }
+    }
+    json += "]";
+    
+    return json;
+}
+
+void Diagnostics::clearLogs() {
+    if (!initialized) return;
+    
+    logEntries.clear();
+    logEvent("Logs cleared");
+}
+
+bool Diagnostics::isBuzzerActive() {
+    return buzzerActive;
+}
+
+void Diagnostics::setBuzzerActive(bool state) {
+    buzzerActive = state;
+}
+
+String Diagnostics::getTimestamp() {
+    unsigned long milliseconds = millis();
+    int seconds = (milliseconds / 1000) % 60;
+    int minutes = (milliseconds / (1000 * 60)) % 60;
+    int hours = (milliseconds / (1000 * 60 * 60)) % 24;
+    
+    char timeString[9];
+    sprintf(timeString, "%02d:%02d:%02d", hours, minutes, seconds);
+    return String(timeString);
+}

