+/**
+ * @file watchdog.cpp
+ * @brief Watchdog timer implementation for system recovery
+ */
+
+#include "watchdog.h"
+#include "../system/diagnostics.h"
+
+bool Watchdog::initialized = false;
+bool Watchdog::enabled = true; // Enabled by default
+unsigned long Watchdog::lastFeedTime = 0;
+
+void Watchdog::begin() {
+    Serial.println("Initializing watchdog timer...");
+    initialized = true;
+    lastFeedTime = millis();
+    
+    // If using external watchdog hardware, initialize the pin
+    // pinMode(WATCHDOG_PIN, OUTPUT);
+    // digitalWrite(WATCHDOG_PIN, HIGH); // Feed watchdog on startup
+    
+    Serial.println("Watchdog timer initialized");
+}
+
+void Watchdog::update() {
+    if (!initialized || !enabled) return;
+    
+    checkWatchdog();
+}
+
+void Watchdog::feed() {
+    if (!initialized) return;
+    
+    lastFeedTime = millis();
+    
+    // If using external watchdog hardware, feed it
+    // digitalWrite(WATCHDOG_PIN, HIGH);
+    // delay(1);
+    // digitalWrite(WATCHDOG_PIN, LOW);
+    
+    // Serial.println("Watchdog fed"); // Debug only
+}
+
+bool Watchdog::isEnabled() {
+    return enabled;
+}
+
+void Watchdog::setEnabled(bool enabled) {
+    Watchdog::enabled = enabled;
+}
+
+void Watchdog::checkWatchdog() {
+    if (!initialized) return;
+    
+    unsigned long now = millis();
+    unsigned long timeSinceLastFeed = now - lastFeedTime;
+    
+    // Check if watchdog has timed out
+    if (timeSinceLastFeed >= WATCHDOG_TIMEOUT) {
+        Serial.println("WATCHDOG TIMEOUT - System reset recommended");
+        Diagnostics::logError("Watchdog timeout detected");
+        
+        // In a real implementation, we might trigger a reset
+        // ESP.restart(); // Uncomment for actual reset
+        
+        // For now, just feed it to prevent continuous resets during development
+        feed();
+    }
+    
+    // Periodically feed the watchdog (every half timeout)
+    if (timeSinceLastFeed >= (WATCHDOG_TIMEOUT / 2)) {
+        feed();
+    }
+}

